def gcdOfStrings(str1: str, str2: str) -> str:
    if len(str1) < len(str2):
        str1, str2 = str2, str1
    gcd_len = 0
    for i in range(1, len(str2) + 1):
        if len(str2) % i == 0 and len(str1) % i == 0:
            gcd_len = i
    candidate = str2[:gcd_len]
    if candidate * (len(str1) // len(candidate)) == str1 and candidate * (len(str2) // len(candidate)) == str2:
        return candidate
    return ""

def kidsWithCandies(candies: list[int], extraCandies: int) -> list[bool]:
    max_candies = max(candies)
    return [c + extraCandies >= max_candies for c in candies]

def canPlaceFlowers(flowerbed: list[int], n: int) -> bool:
    count = 0
    for i in range(len(flowerbed)):
        if flowerbed[i] == 0:
            left_empty = i == 0 or flowerbed[i-1] == 0
            right_empty = i == len(flowerbed)-1 or flowerbed[i+1] == 0
            if left_empty and right_empty:
                flowerbed[i] = 1
                count += 1
                i += 1
    return count >= n

def reverseVowels(s: str) -> str:
    vowels = set('aeiouAEIOU')
    s = list(s)
    l, r = 0, len(s) - 1
    while l < r:
        if s[l] in vowels and s[r] in vowels:
            s[l], s[r] = s[r], s[l]
            l += 1
            r -= 1
        elif s[l] in vowels:
            r -= 1
        elif s[r] in vowels:
            l += 1
        else:
            l += 1
            r -= 1
    return ''.join(s)

def reverseWords(s: str) -> str:
    words = s.split(' ')
    i, j = 0, len(words) - 1
    while i < j:
        words[i], words[j] = words[j], words[i]
        i += 1
        j += 1
    return ' '.join(words)

def increasingTriplet(nums: list[int]) -> bool:
    first = float('inf')
    second = float('inf')
    for n in nums:
        if n <= first:
            first = n
        elif n <= second:
            second = n
        else:
            return True
    return False

def compress(chars: list[str]) -> int:
    write = 0
    read = 0
    while read < len(chars):
        ch = chars[read]
        count = 0
        while read < len(chars) and chars[read] == ch:
            read += 1
            count += 1
        chars[write] = ch
        write += 1
        if count > 1:
            for digit in str(count):
                chars[write] = digit
                write += 1
    return write

def moveZeroes(nums: list[int]) -> None:
    for i in range(len(nums)):
        if nums[i] == 0:
            nums.pop(i)
            nums.append(0)

def isSubsequence(s, t):
    i = j = 0
    while i < len(s) and j < len(t):
        if s[i] == t[j]:
            i += 1
        j += 1
    return i == len(s)

def maxArea(height):
    left, right = 0, len(height) - 1
    max_water = 0
    while left < right:
        area = min(height[left], height[right]) * (right - left)
        max_water = max(max_water, area)
        if height[left] < height[right]:
            left += 1
        else:
            right -= 1
    return max_water

def maxOperations(nums, k):
    freq = {}
    count = 0
    for num in nums:
        complement = k - num
        if complement in freq and freq[complement] > 0:
            count += 1
            freq[complement] -= 1
        else:
            freq[num] = freq.get(num, 0) + 1
    return count

def maxVowels(s, k):
    vowels = set('aeiou')
    count = 0
    for i in range(k):
        if s[i] in vowels:
            count += 1
    max_count = count
    for i in range(k, len(s)):
        if s[i] in vowels:
            count += 1
        if s[i - k] in vowels:
            count -= 1
        if count > max_count:
            max_count = count
    return max_count

def longestOnes(nums, k):
    left = 0
    for right in range(len(nums)):
        if nums[right] == 0:
            k -= 1
        if k < 0:
            if nums[left] == 0:
                k += 1
            left += 1
    return right - left + 1

def longestSubarray(nums):
    left = 0
    zeros = 0
    max_len = 0
    for right in range(len(nums)):
        if nums[right] == 0:
            zeros += 1
        while zeros > 1:
            if nums[left] == 0:
                zeros -= 1
            left += 1
        max_len = max(max_len, right - left)
    return max_len

def largestAltitude(gain):
    max_alt = 0
    curr = 0
    for g in gain:
        curr += g
        if curr > max_alt:
            max_alt = curr
    return max_alt

def pivotIndex(nums):
    total = sum(nums)
    left_sum = 0
    for i in range(len(nums)):
        if left_sum == total - left_sum:
            return i
        left_sum += nums[i]
    return -1

