def equalPairs(grid):
    n = len(grid)
    rows = {}
    for r in range(n):
        row = tuple(grid[r])
        rows[row] = rows.get(row, 0) + 1
    count = 0
    for c in range(n):
        col = tuple(grid[r][c] for r in range(n))
        count += rows.get(col, 0)
    return count

def removeStars(s):
    stack = []
    for c in s:
        if c == '*':
            stack.pop()
        else:
            stack.append(c)
    return ''.join(stack)

def asteroidCollision(asteroids):
    stack = []
    for a in asteroids:
        while stack and a > 0 and stack[-1] < 0:
            if abs(a) > abs(stack[-1]):
                stack.pop()
            elif abs(a) == abs(stack[-1]):
                stack.pop()
                a = 0
            else:
                a = 0
        if a != 0:
            stack.append(a)
    return stack

def decodeString(s):
    stack = []
    for c in s:
        if c != ']':
            stack.append(c)
        else:
            sub = ''
            while stack and stack[-1] != '[':
                sub = stack.pop() + sub
            stack.pop()
            num = ''
            while stack and stack[-1].isdigit():
                num = stack.pop() + num
            stack.append(int(num) * sub)
    return ''.join(stack)

