def predictPartyVictory(senate):
    n = len(senate)
    r_queue = []
    d_queue = []
    for i, s in enumerate(senate):
        if s == 'R':
            r_queue.append(i)
        else:
            d_queue.append(i)
    while r_queue and d_queue:
        r = r_queue.pop(0)
        d = d_queue.pop(0)
        if r < d:
            r_queue.append(r + n)
        else:
            d_queue.append(d + n)
    return "Radiant" if r_queue else "Dire"

def deleteMiddle(head):
    if not head or not head.next:
        return None
    slow = head
    fast = head.next
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
    slow.next = slow.next.next
    return head

def maxDepth(root):
    if not root:
        return 0
    return 1 + max(maxDepth(root.left), maxDepth(root.right))

def leafSimilar(root1, root2):
    def get_leaves_bfs(root):
        if not root:
            return []
        leaves = []
        queue = [root]
        while queue:
            node = queue.pop(0)
            if not node.left and not node.right:
                leaves.append(node.val)
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        return leaves
    return get_leaves_bfs(root1) == get_leaves_bfs(root2)

def goodNodes(root):
    def dfs(node, max_val):
        if not node:
            return 0
        good = 1 if node.val >= max_val else 0
        max_val = max(max_val, node.val)
        return good + dfs(node.left, max_val) + dfs(node.right, max_val)
    return dfs(root, float('-inf'))

def pathSum(root, targetSum):
    def dfs(node, curr_sum):
        if not node:
            return 0
        curr_sum += node.val
        count = 1 if curr_sum == targetSum else 0
        count += dfs(node.left, curr_sum)
        count += dfs(node.right, curr_sum)
        return count
    return dfs(root, 0)

def longestZigZag(root):
    ans = 0
    def dfs(node, direction, length):
        nonlocal ans
        if not node:
            return
        ans = max(ans, length)
        if direction == 'left':
            dfs(node.left, 'right', length + 1)
            dfs(node.right, 'left', 1)
        else:
            dfs(node.right, 'left', length + 1)
            dfs(node.left, 'right', 1)
    dfs(root, 'left', 0)
    dfs(root, 'right', 0)
    return ans

def lowestCommonAncestor(root, p, q):
    if not root or root == p or root == q:
        return root
    left = lowestCommonAncestor(root.left, p, q)
    right = lowestCommonAncestor(root.right, p, q)
    if left and right:
        return root
    return left if left else right

def rightSideView(root):
    if not root:
        return []
    result = []
    curr = root
    while curr:
        result.append(curr.val)
        curr = curr.right
    return result

def maxLevelSum(root):
    if not root:
        return 0
    max_sum = float('-inf')
    max_level = 1
    level = 1
    queue = [root]
    while queue:
        level_sum = 0
        level_size = len(queue)
        for _ in range(level_size):
            node = queue.pop(0)
            level_sum += node.val
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        if level_sum > max_sum:
            max_sum = level_sum
            max_level = level
        level += 1
    return max_level

def searchBST(root, val):
    if not root:
        return None
    if root.val == val:
        return root
    if val < root.val:
        return searchBST(root.left, val)
    else:
        return searchBST(root.right, val)

def deleteNode(root, key):
    if not root:
        return None
    if key < root.val:
        root.left = deleteNode(root.left, key)
    elif key > root.val:
        root.right = deleteNode(root.right, key)
    else:
        if not root.left:
            return root.right
        if not root.right:
            return root.left
        temp = root.right
        while temp.left:
            temp = temp.left
        root.val = temp.val
    return root

def canVisitAllRooms(rooms):
    visited = set()
    def dfs(room):
        if room in visited:
            return
        visited.add(room)
        for key in rooms[room]:
            dfs(key)
    dfs(0)
    return len(visited) == len(rooms)

def findCircleNum(isConnected):
    n = len(isConnected)
    visited = [False] * n
    provinces = 0
    def dfs(city):
        for neighbor in range(n):
            if isConnected[city][neighbor] == 1 and not visited[neighbor]:
                visited[neighbor] = True
                dfs(neighbor)
    for i in range(n):
        if not visited[i]:
            provinces += 1
            dfs(i)
    return provinces

def minReorder(n, connections):
    graph = [[] for _ in range(n)]
    for a, b in connections:
        graph[a].append((b, 1))
        graph[b].append((a, 0))
    seen = {0}
    changes = 0
    def dfs(city):
        nonlocal changes
        for neighbor, direction in graph[city]:
            if neighbor not in seen:
                seen.add(neighbor)
                if direction == 1:
                    changes += 1
                dfs(neighbor)
    dfs(0)
    return changes

def calcEquation(equations, values, queries):
    graph = {}
    for (a, b), v in zip(equations, values):
        if a not in graph:
            graph[a] = []
        if b not in graph:
            graph[b] = []
        graph[a].append((b, v))
        graph[b].append((a, 1.0 / v))
    def dfs(start, end, visited):
        if start not in graph or end not in graph:
            return -1.0
        if start == end:
            return 1.0
        visited.add(start)
        for neighbor, weight in graph[start]:
            if neighbor not in visited:
                result = dfs(neighbor, end, visited)
                if result != -1.0:
                    return result
        return -1.0
    results = []
    for a, b in queries:
        results.append(dfs(a, b, set()))
    return results

from collections import deque
def nearestExit(maze, entrance):
    m, n = len(maze), len(maze[0])
    q = deque([(entrance[0], entrance[1], 0)])
    maze[entrance[0]][entrance[1]] = '+'
    directions = [(0,1),(0,-1),(1,0),(-1,0)]
    while q:
        r, c, steps = q.popleft()
        if (r == 0 or r == m-1 or c == 0 or c == n-1) and steps > 0:
            return steps
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n and maze[nr][nc] == '.':
                maze[nr][nc] = '+'
                q.append((nr, nc, steps + 1))
    return -1

from collections import deque
def orangesRotting(grid):
    m, n = len(grid), len(grid[0])
    q = deque()
    fresh = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 2:
                q.append((i, j, 0))
            elif grid[i][j] == 1:
                fresh += 1
    if fresh == 0:
        return 0
    minutes = 0
    directions = [(0,1),(0,-1),(1,0),(-1,0)]
    while q:
        r, c, t = q.popleft()
        minutes = max(minutes, t)
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n and grid[nr][nc] == 1:
                grid[nr][nc] = 2
                fresh -= 1
                q.append((nr, nc, t + 1))
    return minutes if fresh == 0 else -1

import heapq
class SmallestInfiniteSet:
    def __init__(self):
        self.added = []
        self.current = 1
    def popSmallest(self):
        if self.added:
            return heapq.heappop(self.added)
        val = self.current
        self.current += 1
        return val
    def addBack(self, num):
        if num < self.current and num not in self.added:
            heapq.heappush(self.added, num)

def totalCost(costs, k, candidates):
    import heapq
    n = len(costs)
    left = 0
    right = n - 1
    left_heap = []
    right_heap = []
    for i in range(candidates):
        if left <= right:
            heapq.heappush(left_heap, costs[left])
            left += 1
        if left <= right:
            heapq.heappush(right_heap, costs[right])
            right -= 1
    total = 0
    for _ in range(k):
        if right_heap and (not left_heap or right_heap[0] <= left_heap[0]):
            total += heapq.heappop(right_heap)
            if left <= right:
                heapq.heappush(right_heap, costs[right])
                right -= 1
        else:
            total += heapq.heappop(left_heap)
            if left <= right:
                heapq.heappush(left_heap, costs[left])
                left += 1
    return total

