def findPeakElement(nums):
    left, right = 0, len(nums) - 1
    while left < right:
        mid = (left + right) // 2
        if nums[mid] > nums[mid + 1]:
            right = mid
        else:
            left = mid + 1
    return left

def minEatingSpeed(piles, h):
    left, right = 1, max(piles)
    while left < right:
        mid = (left + right) // 2
        hours = sum(pile // mid for pile in piles)
        if hours <= h:
            right = mid
        else:
            left = mid + 1
    return left

def letterCombinations(digits):
    if not digits:
        return []
    mapping = {
        '2': 'abc', '3': 'def', '4': 'ghi', '5': 'jkl',
        '6': 'mno', '7': 'pqrs', '8': 'tuv', '9': 'wxyz'
    }
    res = []
    def backtrack(idx, path):
        if idx == len(digits):
            res.append(''.join(path))
            return
        for c in mapping[digits[idx]]:
            path.append(c)
            backtrack(idx + 1, path)
            path.pop()
    backtrack(0, [])
    return res

def combinationSum3(k, n):
    res = []
    def backtrack(start, path, remaining):
        if len(path) == k and remaining == 0:
            res.append(path[:])
            return
        if len(path) > k or remaining < 0:
            return
        for i in range(start, 9):
            path.append(i)
            backtrack(i + 1, path, remaining - i)
            path.pop()
    backtrack(1, [], n)
    return res

def tribonacci(n):
    if n == 0:
        return 0
    if n <= 2:
        return 1
    t0, t1, t2 = 0, 1, 1
    for i in range(3, n + 1):
        t3 = t0 + t1 + t2
        t0, t1, t2 = t1, t2, t3
    return t2

def minCostClimbingStairs(cost):
    n = len(cost)
    dp0, dp1 = cost[0], cost[1]
    for i in range(2, n):
        dp2 = cost[i] + min(dp0, dp1)
        dp0, dp1 = dp1, dp2
    return min(dp0, dp1)

def rob(nums):
    if not nums:
        return 0
    if len(nums) == 1:
        return nums[0]
    dp = [0] * len(nums)
    dp[0] = nums[0]
    dp[1] = max(nums[0], nums[1])
    for i in range(2, len(nums)):
        dp[i] = max(dp[i-1], dp[i-2] + nums[i])
    return dp[-1]

def uniquePaths(m, n):
    dp = [[1] * n for _ in range(m)]
    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = dp[i-1][j] + dp[i][j-1]
    return dp[m-1][n-1]

def longestCommonSubsequence(text1, text2):
    m, n = len(text1), len(text2)
    dp = [[0] * n for _ in range(m)]
    for i in range(m):
        for j in range(n):
            if text1[i] == text2[j]:
                dp[i][j] = (dp[i-1][j-1] if i > 0 and j > 0 else 0) + 1
            else:
                top = dp[i-1][j] if i > 0 else 0
                left = dp[i][j-1] if j > 0 else 0
                dp[i][j] = max(top, left)
    return dp[m-1][n-1]

def minDistance(word1, word2):
    m, n = len(word1), len(word2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if word1[i-1] == word2[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
    return dp[m][n]

def countBits(n):
    ans = [0] * (n + 1)
    for i in range(1, n + 1):
        ans[i] = ans[i >> 1] + (i & 1)
    return ans

def singleNumber(nums):
    result = 0
    for num in nums:
        result ^= num
    return result

def minFlips(a, b, c):
    flips = 0
    while a > 0 or b > 0 or c > 0:
        bit_a = a & 1
        bit_b = b & 1
        bit_c = c & 1
        if (bit_a | bit_b) != bit_c:
            if bit_c == 0:
                flips += 1
            else:
                flips += 1
        a >>= 1
        b >>= 1
        c >>= 1
    return flips

class Trie:
    def __init__(self):
        self.children = {}
        self.is_end = False

    def insert(self, word):
        node = self
        for ch in word:
            if ch not in node.children:
                node.children[ch] = Trie()
            node = node.children[ch]
        node.is_end = True

    def search(self, word):
        node = self
        for ch in word:
            if ch not in node.children:
                return False
            node = node.children[ch]
        return node.is_end

    def startsWith(self, prefix):
        node = self
        for ch in prefix:
            if ch not in node.children:
                return False
            node = node.children[ch]
        return True

def eraseOverlapIntervals(intervals):
    if not intervals:
        return 0
    intervals.sort(key=lambda x: x[1])
    count = 0
    end = float('-inf')
    for s, e in intervals:
        if s >= end:
            end = e
        else:
            count += 1
    return count

def findMinArrowShots(points):
    if not points:
        return 0
    points.sort(key=lambda x: x[1])
    arrows = 1
    end = points[0][1]
    for s, e in points[1:]:
        if s >= end:
            arrows += 1
            end = e
    return arrows

def dailyTemperatures(temperatures):
    n = len(temperatures)
    answer = [0] * n
    stack = []
    for i in range(n):
        while stack and temperatures[i] > temperatures[stack[-1]]:
            idx = stack.pop()
            answer[idx] = i - idx
        stack.append(i)
    return answer

class StockSpanner:
    def __init__(self):
        self.stack = []
    def next(self, price):
        span = 1
        while self.stack and self.stack[-1][0] < price:
            span += self.stack.pop()[1]
        self.stack.append((price, span))
        return span

def suggestedProducts(products, searchWord):
    products.sort()
    class TrieNode:
        def __init__(self):
            self.children = {}
            self.words = []
    root = TrieNode()
    for p in products:
        cur = root
        for c in p:
            if c not in cur.children:
                cur.children[c] = TrieNode()
            cur = cur.children[c]
            if len(cur.words) < 3:
                cur.words.append(p)
    res = []
    cur = root
    for c in searchWord:
        if cur and c in cur.children:
            cur = cur.children[c]
            res.append(cur.words[:])
        else:
            cur = None
            res.append([])
    return res
